// Trait aliases resolve through rustc and satisfy the hidden render-trait
// witness generated by `#[rsjs(component)]`.

#[allow(unused_imports)]
use proa_core::WebRenderSync as WRS;
#[allow(unused_imports)]
use proa_core::{WebContext, WriteBuf, WriteError};
use rsjs::rsjs;

pub struct Counter;

#[rsjs(component)]
impl<B: WriteBuf, L: proa_core::DataLoader> WRS<L, B> for Counter {
    fn render(self, cx: &mut WebContext<L, B>) -> Result<(), WriteError> {
        proa_macros::html_sync! {
            <div>"hi"</div>
        }
        .render(cx)
    }
}

fn main() {}
